// Biến company_knowledge.json thành danh sách 'documents' để nạp vào Pinecone.
// Mỗi entry (sản phẩm, quy trình, chính sách, FAQ) → 1 document có `text` + metadata.

const root = $input.first().json.data || $input.first().json;
const company = root.company || {};
const products = root.products || [];
const processes = root.processes || [];
const policies = root.policies || {};
const faqs = root.faq || [];

const vnd = (n) => (typeof n === 'number' && n > 0 ? n.toLocaleString('vi-VN') + 'đ' : 'Liên hệ báo giá');
const docs = [];

// --- Thông tin công ty ---
if (company.name) {
  docs.push({
    json: {
      text: [
        `THÔNG TIN CÔNG TY: ${company.name} — ${company.tagline || ''}`,
        `Hotline: ${company.hotline || ''} | Email: ${company.email || ''}`,
        `Website: ${company.website || ''} | Địa chỉ: ${company.address || ''}`,
        `Giờ làm việc: ${company.working_hours || ''}`,
        `Thành lập: ${company.founded || ''} | Quy mô: ${company.employees || ''} nhân viên`,
        `Mô tả: ${company.description || ''}`
      ].filter(Boolean).join('\n'),
      doc_type: 'company_info',
      ref_id: 'company',
      title: company.name,
      category: 'Thông tin công ty'
    }
  });
}

// --- Sản phẩm / Dịch vụ ---
for (const p of products) {
  const features = Array.isArray(p.features)
    ? p.features.map(f => `  - ${f}`).join('\n')
    : (Array.isArray(p.scope) ? p.scope.map(f => `  - ${f}`).join('\n') : '');
  const techList = Array.isArray(p.technologies) ? `Công nghệ: ${p.technologies.join(', ')}` : '';

  docs.push({
    json: {
      text: [
        `SẢN PHẨM/DỊCH VỤ: ${p.name} (mã ${p.id})`,
        `Danh mục: ${p.category}`,
        `Giá: ${vnd(p.price)} ${p.price_unit || ''}`.trim(),
        `Tình trạng: ${p.in_stock ? 'Còn hàng / Đang cung cấp' : 'Hết hàng'}`,
        p.warranty_months ? `Bảo hành: ${p.warranty_months} tháng` : '',
        p.support ? `Hỗ trợ: ${p.support}` : '',
        `Mô tả: ${p.description}`,
        features ? `Tính năng/Phạm vi:\n${features}` : '',
        techList,
        p.process ? `Quy trình: ${p.process}` : '',
        p.duration ? `Thời gian: ${p.duration}` : '',
        Array.isArray(p.tags) && p.tags.length ? `Từ khóa: ${p.tags.join(', ')}` : ''
      ].filter(Boolean).join('\n'),
      doc_type: 'product',
      ref_id: p.id,
      title: p.name,
      category: p.category
    }
  });
}

// --- Quy trình nội bộ ---
for (const pr of processes) {
  const steps = Array.isArray(pr.steps) ? pr.steps.join('\n') : '';
  docs.push({
    json: {
      text: [
        `QUY TRÌNH: ${pr.name} (mã ${pr.id})`,
        `Phòng ban: ${pr.department}`,
        steps ? `Các bước:\n${steps}` : '',
        pr.sla ? `SLA: ${pr.sla}` : '',
        pr.discount_policy ? `Chính sách giảm giá: ${pr.discount_policy}` : '',
        pr.note ? `Lưu ý: ${pr.note}` : '',
        pr.contact ? `Liên hệ: ${pr.contact}` : ''
      ].filter(Boolean).join('\n'),
      doc_type: 'process',
      ref_id: pr.id,
      title: pr.name,
      category: pr.department
    }
  });
}

// --- Chính sách ---
const policyLabels = {
  work_from_home: 'Chính sách Làm việc từ xa (WFH)',
  overtime: 'Chính sách Làm thêm giờ (OT)',
  equipment: 'Chính sách Trang thiết bị',
  confidentiality: 'Chính sách Bảo mật thông tin',
  training: 'Chính sách Đào tạo',
  code_of_conduct: 'Quy tắc Ứng xử'
};
for (const [key, value] of Object.entries(policies)) {
  const label = policyLabels[key] || key;
  docs.push({
    json: {
      text: `CHÍNH SÁCH — ${label}:\n${value}`,
      doc_type: 'policy',
      ref_id: `policy-${key}`,
      title: label,
      category: 'Chính sách'
    }
  });
}

// --- FAQ ---
faqs.forEach((f, i) => {
  docs.push({
    json: {
      text: `CÂU HỎI THƯỜNG GẶP:\nHỏi: ${f.q}\nĐáp: ${f.a}`,
      doc_type: 'faq',
      ref_id: `faq-${i + 1}`,
      title: f.q,
      category: 'FAQ'
    }
  });
});

if (!docs.length) {
  throw new Error('Không có document nào được tạo. Kiểm tra lại nội dung company_knowledge.json.');
}

console.log(`Đã tạo ${docs.length} documents từ company_knowledge.json`);
return docs;
